examples.setupTemplate:
val ground = MonarchTheme.colors.bgMuted
val sun = MonarchTheme.colors.borderStrong
val hill = MonarchTheme.colors.textSubtle
// A grey placeholder with an image glyph, as the web shows while there is no picture.
val picture = object : Painter() {
    override val intrinsicSize: Size = Size.Unspecified
    override fun DrawScope.onDraw() {
        drawRect(ground)
        drawCircle(sun, radius = size.minDimension * 0.15f, center = Offset(size.width * 0.5f, size.height * 0.3f))
        val peak = Path().apply {
            moveTo(0f, size.height)
            lineTo(size.width * 0.45f, size.height * 0.45f)
            lineTo(size.width, size.height * 0.7f)
            lineTo(size.width, size.height)
            close()
        }
        drawPath(peak, hill)
    }
}
var images by remember {
    mutableStateOf(
        listOf(
        MonarchAiGeneratedImage({{images.0.id}}, picture, {{images.0.alt}}),
        MonarchAiGeneratedImage({{images.1.id}}, picture, {{images.1.alt}}),
        MonarchAiGeneratedImage({{images.2.id}}, picture, {{images.2.alt}}),
        MonarchAiGeneratedImage({{images.3.id}}, picture, {{images.3.alt}}),
        ),
    )
}
var chosen by remember { mutableStateOf<String?>(null) }

